'use strict';
const fs = require('fs');
const path = require('path');
const test = require('node:test');
const assert = require('node:assert/strict');
const { loadFixture, replay, browserSpawn } = require('../lib/replay');
const { MockHost } = require('../lib/mock-host');
const fixtureNames = fs.readdirSync(path.join(__dirname, '..', 'fixtures')).filter(f => f.endsWith('.json')).map(f => f.slice(0, -5));

test('sample opener uses open', () => assert.equal(loadFixture('oauth-open').spawn.file, 'open'));
test('sample opener carries a complete HTTPS URL', () => assert.match(loadFixture('oauth-open').spawn.args[0], /^https:\/\//));
test('sample opener environment is preserved', () => assert.deepEqual(loadFixture('oauth-open').spawn.env, { DISPLAY: ':0', WAYLAND_DISPLAY: 'tether', BROWSER: 'open' }));
test('sample opener expected exit is zero', () => assert.equal(loadFixture('oauth-open').expect.exit, 0));
test('xdg-open works without BROWSER', () => { const f = loadFixture('oauth-xdg-open'); assert.equal(f.spawn.file, 'xdg-open'); assert.equal(f.spawn.env.BROWSER, undefined); });
test('xdg-open carries an HTTPS URL', () => assert.match(loadFixture('oauth-xdg-open').spawn.args[0], /^https:\/\//));
test('sensible-browser fallback is represented', () => assert.equal(loadFixture('oauth-sensible-browser').spawn.file, 'sensible-browser'));
test('missing DISPLAY and Wayland means no browser spawn', () => assert.equal(browserSpawn({ BROWSER: 'open' }), null));
test('DISPLAY permits configured BROWSER opener', () => assert.equal(browserSpawn({ DISPLAY: ':0', BROWSER: 'open' }).file, 'open'));
test('Wayland permits fallback opener', () => assert.equal(browserSpawn({ WAYLAND_DISPLAY: 'tether' }).file, 'xdg-open'));
test('opener preserves supplied environment', () => assert.deepEqual(browserSpawn({ DISPLAY: ':0', WAYLAND_DISPLAY: 'tether' }).env, { DISPLAY: ':0', WAYLAND_DISPLAY: 'tether' }));
test('opener handles unrelated HTTPS hosts identically', () => assert.equal(browserSpawn({ DISPLAY: ':0' }, 'xdg-open', 'https://docs.example.org/guide').args[0], 'https://docs.example.org/guide'));
test('git-status fixture preserves executable', () => assert.equal(loadFixture('git-status').spawn.file, 'git'));
test('git-status fixture preserves arguments', () => assert.ok(loadFixture('git-status').spawn.args.includes('status')));
test('git-commit fixture preserves message', () => assert.deepEqual(loadFixture('git-commit').spawn.args, ['commit', '-m', 'fixture commit']));
test('search fixture preserves executable', () => assert.equal(loadFixture('rg-search').spawn.file, 'rg'));
test('search fixture preserves arguments', () => assert.deepEqual(loadFixture('rg-search').spawn.args, ['--line-number', 'oauth', 'src']));
test('shell pipeline uses bash -c', () => { const s = loadFixture('bash-pipeline').spawn; assert.equal(s.file, 'bash'); assert.equal(s.args[0], '-c'); assert.equal(typeof s.args[1], 'string'); assert.equal(s.shell, true); });
test('package lifecycle uses sh -c', () => { const s = loadFixture('npm-lifecycle-sh').spawn; assert.equal(s.file, 'sh'); assert.equal(s.args[0], '-c'); });
test('all fixtures replay without throwing', () => fixtureNames.forEach(name => assert.doesNotThrow(() => replay(loadFixture(name)))));
test('replay sends exact spawn shape', () => { const { result, host } = replay(loadFixture('git-status')); assert.equal(host.requests[0].kind, 'spawn'); assert.equal(result.code, 0); });
test('interactive defaults are explicitly false', () => fixtureNames.forEach(name => assert.equal(loadFixture(name).spawn.interactive, false)));
test('cancel returns exit 130 generically', () => assert.deepEqual(new MockHost().handle({ kind: 'cancel', id: 'job-1' }), { kind: 'exit', id: 'job-1', code: 130 }));
